<script setup lang="ts">import{onMounted,ref}from'vue';import{ApiError,request}from'../api/client';interface User{id:number;username:string;nickname:string;status:number;wallet_available:number;wallet_frozen:number;wallet_status:string;private_muted_until?:string;group_muted_until?:string;mute_reason:string}const items=ref<User[]>([]),q=ref(''),error=ref(''),selected=ref<User|null>(null),action=ref('disable'),reason=ref(''),until=ref('');async function load(){try{items.value=await request<User[]>('/v1/ops/users?q='+encodeURIComponent(q.value))}catch(e){error.value=e instanceof ApiError?e.message:'加载失败'}}function open(v:User){selected.value=v;reason.value='';until.value='';action.value=v.status===1?'disable':'enable'}async function submit(){if(!selected.value)return;await request(`/v1/ops/users/${selected.value.id}/control`,{method:'POST',body:JSON.stringify({action:action.value,reason:reason.value,until:until.value?new Date(until.value).toISOString():null})});selected.value=null;await load()}onMounted(load)</script>
<template><div class="page"><div class="heading"><div><h1>用户与设备</h1><p>账号状态、会话设备、聊天限制与钱包概览</p></div><form @submit.prevent="load"><input v-model="q" placeholder="用户名或昵称"><button>查询</button></form></div><p v-if="error" class="error">{{error}}</p><div class="table"><table><thead><tr><th>用户</th><th>平台钱包</th><th>私聊</th><th>群聊</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="u in items" :key="u.id"><td><strong>{{u.nickname}}</strong><small>@{{u.username}} · ID {{u.id}}</small></td><td>¥{{(u.wallet_available/100).toFixed(2)}} / 冻结 ¥{{(u.wallet_frozen/100).toFixed(2)}}</td><td>{{u.private_muted_until?'受限':'正常'}}</td><td>{{u.group_muted_until?'受限':'正常'}}</td><td>{{u.status===1?'正常':'停用'}}</td><td><button class="link" @click="open(u)">管控</button></td></tr></tbody></table></div><div v-if="selected" class="backdrop" @click.self="selected=null"><form class="dialog" @submit.prevent="submit"><h2>用户管控</h2><p>{{selected.nickname}} · @{{selected.username}}</p><label>操作<select v-model="action"><option value="enable">启用账号</option><option value="disable">停用账号</option><option value="mute_private">限制私聊</option><option value="unmute_private">解除私聊限制</option><option value="mute_group">限制群聊</option><option value="unmute_group">解除群聊限制</option><option value="revoke_sessions">下线所有设备</option></select></label><label v-if="action==='mute_private'||action==='mute_group'">截止时间（留空为永久）<input v-model="until" type="datetime-local"></label><label>原因<textarea v-model.trim="reason" required minlength="2" maxlength="500"></textarea></label><div class="actions"><button type="button" @click="selected=null">取消</button><button class="primary">确认</button></div></form></div></div></template>
<style scoped>@import '../design/admin-page.css';</style>
